51			$bulk = Bulk::get_instance();
52			$stat = 0;
53	
54			// Sum the counts of each context.
55			foreach ( imagify_get_context_names() as $context ) {
56				$stat += $bulk->get_bulk_instance( $context )->has_optimized_media_without_nextgen();
