import { execSync } from 'child_process';
import * as path from 'path';

const REPO_ROOT = path.resolve( __dirname, '../../../' );

/**
 * Run a WP-CLI command inside the wp-env container.
 * Returns trimmed stdout. Throws on non-zero exit.
 */
export function wpCli( command: string ): string {
	return execSync( `npx @wordpress/env run cli wp ${ command }`, {
		cwd: REPO_ROOT,
		encoding: 'utf8',
		stdio: [ 'pipe', 'pipe', 'pipe' ],
	} ).trim();
}

/** Returns true if a BackWPup license key is available in the environment. */
export function hasLicenseKey(): boolean {
	return !! process.env.BACKWPUP_TESTS_LICENSE_KEY;
}

