import { Page, Locator } from '@playwright/test';

/**
 * Page object for the BackWPup onboarding flow.
 * URL: /wp-admin/admin.php?page=backwpuponboarding
 *
 * Three steps rendered as <article data-step="1|2|3"> inside #backwpup-onboarding-panes.
 * Steps 2 and 3 start hidden (Tailwind "hidden" class) and are shown by JS.
 */
export class OnboardingPage {
	readonly page: Page;

	// Step panels
	readonly step1Panel: Locator;
	readonly step2Panel: Locator;
	readonly step3Panel: Locator;

	// Step 1 — "What do you want to backup?"
	readonly continueToStep2: Locator;

	// Step 2 — "When?"
	readonly continueToStep3: Locator;

	// Step 3 — "Where to store?"
	readonly websiteServerStorage: Locator;
	readonly submitOnboarding: Locator;

	constructor( page: Page ) {
		this.page = page;

		this.step1Panel = page.locator( 'article[data-step="1"]' );
		this.step2Panel = page.locator( 'article[data-step="2"]' );
		this.step3Panel = page.locator( 'article[data-step="3"]' );

		// Buttons identified by their JS trigger class (rendered as js-backwpup-{trigger})
		this.continueToStep2 = page.locator( 'button.js-backwpup-onboarding-step-2' );
		this.continueToStep3 = page.locator( 'button.js-backwpup-onboarding-step-3' );
		this.websiteServerStorage = page.locator( 'button.js-backwpup-toggle-storage[data-storage="FOLDER"]' );
		this.submitOnboarding = page.locator( 'button.js-backwpup-onboarding-submit-form' );
	}

	async goto(): Promise<void> {
		await this.page.goto( '/wp-admin/admin.php?page=backwpuponboarding' );
		await this.page.waitForLoadState( 'networkidle' );
	}
}

