	} );

	test( 'Dashboard loads without fatal errors', async ( { page } ) => {
		const dashboard = new DashboardPage( page );
		await dashboard.goto();
		await dashboard.expectNoFatalError();
	} );

	test( 'Settings page loads without fatal errors', async ( { page } ) => {
		const settings = new SettingsPage( page );
		await settings.goto();
		await settings.expectNoFatalError();
		await expect( settings.settingsForm ).toBeVisible();
	} );

	test( 'Settings page has tab navigation', async ( { page } ) => {
		const settings = new SettingsPage( page );
		await settings.goto();
		await expect( settings.tabBar ).toBeVisible();
	} );

	test( 'Backups page loads without fatal errors', async ( { page } ) => {
		const backups = new BackupsPage( page );
		await backups.goto();
		await backups.expectNoFatalError();
	} );

	test( 'Legacy Jobs page loads without fatal errors', async ( { page } ) => {
		await page.goto( '/wp-admin/admin.php?page=backwpupjobs' );
		await page.waitForLoadState( 'networkidle' );
		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
	} );

	test( 'Logs page loads without fatal errors', async ( { page } ) => {
		await page.goto( '/wp-admin/admin.php?page=backwpuplogs' );
		await page.waitForLoadState( 'networkidle' );
		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
	} );

	test( 'Plugin can be deactivated and reactivated without errors', async () => {
		const deactivate = wpCli( 'plugin deactivate backwpup-pro' );
		expect( deactivate ).toContain( 'Deactivated' );

		const activate = wpCli( 'plugin activate backwpup-pro' );
		expect( activate ).toContain( 'Activated' );
	} );
} );

