import { test, expect } from '@playwright/test';
import { loginAsAdmin } from '../fixtures/auth';
import { wpCli } from '../fixtures/wp-cli';

/**
 * Legacy Jobs admin page tests.
 *
 * Verifies that the jobs list renders correctly and that a seed job
 * created by bin/dev-seed.sh appears in the table.
 *
 * Tests that trigger actual backup runs require a license key and are
 * skipped when BACKWPUP_TESTS_LICENSE_KEY is not set.
 */
test.describe( 'BackWPup — Legacy Jobs list', () => {
	test.beforeEach( async ( { page } ) => {
		await loginAsAdmin( page );
	} );

	test( 'Jobs page loads and displays the jobs table', async ( { page } ) => {
		await page.goto( '/wp-admin/admin.php?page=backwpupjobs' );
		await page.waitForLoadState( 'networkidle' );

		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
		// The WP_List_Table renders a <table> with class widefat.
		await expect( page.locator( 'table.widefat' ) ).toBeVisible();
	} );

	test( 'Seed job appears in the jobs list', async ( { page } ) => {
		await page.goto( '/wp-admin/admin.php?page=backwpupjobs' );
		await page.waitForLoadState( 'networkidle' );

		const seedRow = page.locator( 'td', { hasText: 'BackWPup E2E Seed Job' } );
		const count = await seedRow.count();

		if ( count === 0 ) {
			test.skip( true, 'Seed job not found — run bin/dev-seed.sh first' );
			return;
		}

		await expect( seedRow.first() ).toBeVisible();
	} );

	test( 'Job edit page loads for the seed job', async ( { page } ) => {
		// Find the job ID via WP-CLI.
		const jobsJson = wpCli( "eval 'echo json_encode( BackWPup_Option::get_job_ids() );'" );
		let seedJobId: string | null = null;

		try {
			const ids = JSON.parse( jobsJson ) as number[];
			for ( const id of ids ) {
				const name = wpCli( `eval 'echo BackWPup_Option::get( ${ id }, "name" );'` );
				if ( name.trim() === 'BackWPup E2E Seed Job' ) {
					seedJobId = String( id );
					break;
				}
			}
		} catch {
			test.skip( true, 'Could not parse jobs list — run bin/dev-seed.sh first' );
			return;
		}

		if ( ! seedJobId ) {
			test.skip( true, 'Seed job not found — run bin/dev-seed.sh first' );
			return;
		}

		await page.goto( `/wp-admin/admin.php?page=backwpupeditjob&jobid=${ seedJobId }` );
		await page.waitForLoadState( 'networkidle' );

		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
		await expect( page.locator( '#backwpup-page, .wrap' ) ).toBeVisible();
	} );
} );

