import { test, expect } from '@playwright/test';
import { loginAsAdmin } from '../fixtures/auth';
import { wpCli } from '../fixtures/wp-cli';
import { OnboardingPage } from '../pages/onboarding';

/**
 * Onboarding flow tests.
 *
 * The onboarding is driven by the `backwpup_onboarding` site option:
 * - true  → all BackWPup pages redirect to page=backwpuponboarding
 * - false/absent → onboarding is complete
 *
 * Each test resets to onboarding state and cleans up afterward so it
 * does not affect the smoke or jobs specs.
 */
test.describe( 'BackWPup — Onboarding flow', () => {
	test.beforeEach( async ( { page } ) => {
		// Re-enable onboarding for this test.
		wpCli( "eval \"update_site_option( 'backwpup_onboarding', true );\"" );
		await loginAsAdmin( page );
	} );

	test.afterEach( () => {
		// Always restore onboarding-complete state so other specs are unaffected.
		wpCli( "eval \"delete_site_option( 'backwpup_onboarding' );\"" );
	} );

	test( 'Onboarding page loads and shows step 1', async ( { page } ) => {
		const onboarding = new OnboardingPage( page );
		await onboarding.goto();

		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
		await expect( onboarding.step1Panel ).toBeVisible();
		await expect( onboarding.continueToStep2 ).toBeVisible();
	} );

	test( 'BackWPup pages redirect to onboarding while active', async ( { page } ) => {
		await page.goto( '/wp-admin/admin.php?page=backwpupjobs' );
		await page.waitForLoadState( 'networkidle' );

		expect( page.url() ).toContain( 'page=backwpuponboarding' );
	} );

	test( 'Step 1 → Step 2: advance with Save & Continue', async ( { page } ) => {
		const onboarding = new OnboardingPage( page );
		await onboarding.goto();

		await onboarding.continueToStep2.click();

		await expect( onboarding.step2Panel ).toBeVisible( { timeout: 5_000 } );
		await expect( onboarding.continueToStep3 ).toBeVisible();
	} );

	test( 'Step 2 → Step 3: advance with Save & Continue', async ( { page } ) => {
		const onboarding = new OnboardingPage( page );
		await onboarding.goto();

		await onboarding.continueToStep2.click();
		await expect( onboarding.step2Panel ).toBeVisible( { timeout: 5_000 } );

		await onboarding.continueToStep3.click();

		await expect( onboarding.step3Panel ).toBeVisible( { timeout: 5_000 } );
		await expect( onboarding.websiteServerStorage ).toBeVisible();
	} );

	test( 'Step 3: selecting Website Server enables the submit button', async ( { page } ) => {
		const onboarding = new OnboardingPage( page );
		await onboarding.goto();

		await onboarding.continueToStep2.click();
		await expect( onboarding.step2Panel ).toBeVisible( { timeout: 5_000 } );
		await onboarding.continueToStep3.click();
		await expect( onboarding.step3Panel ).toBeVisible( { timeout: 5_000 } );

		// Submit is disabled until a storage is selected.
		await expect( onboarding.submitOnboarding ).toBeDisabled();

		await onboarding.websiteServerStorage.click();

		await expect( onboarding.submitOnboarding ).toBeEnabled( { timeout: 5_000 } );
	} );

	test( 'Complete full onboarding: submitting redirects to first backup page', async ( { page } ) => {
		const onboarding = new OnboardingPage( page );
		await onboarding.goto();

		// Step 1 → Step 2
		await onboarding.continueToStep2.click();
		await expect( onboarding.step2Panel ).toBeVisible( { timeout: 5_000 } );

		// Step 2 → Step 3
		await onboarding.continueToStep3.click();
		await expect( onboarding.step3Panel ).toBeVisible( { timeout: 5_000 } );

		// Step 3: choose Website Server (local folder) and submit
		await onboarding.websiteServerStorage.click();
		await expect( onboarding.submitOnboarding ).toBeEnabled( { timeout: 5_000 } );
		await onboarding.submitOnboarding.click();

		// After submission the plugin redirects to the first backup page
		// and deletes the backwpup_onboarding option.
		await page.waitForURL( '**/page=backwpupfirstbackup**', { timeout: 15_000 } );
		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
	} );
} );

