import { Page, Locator } from '@playwright/test';

/**
 * Page object for the BackWPup onboarding flow.
 * URL: /wp-admin/admin.php?page=backwpuponboarding
 *
 * Three steps rendered as <article data-step="1|2|3"> inside #backwpup-onboarding-panes.
 * Steps 2 and 3 start hidden (Tailwind "hidden" class) and are shown by JS.
 */
export class OnboardingPage {
	readonly page: Page;

	// Each step is active when its unique button is visible:
	// Step 1 → continueToStep2, Step 2 → continueToStep3, Step 3 → websiteServerStorage
	readonly continueToStep2: Locator;
	readonly continueToStep3: Locator;
	readonly websiteServerStorage: Locator;
	readonly submitOnboarding: Locator;

	constructor( page: Page ) {
		this.page = page;

		// Scoped to their article so each locator is unique.
		// js-backwpup-onboarding-step-2 appears twice in the DOM: once as
		// step 1's "Save & Continue" and once as step 3's "Back to When".
		// Scoping to the article resolves strict-mode violations and ties
		// visibility to whether the step is currently shown.
		this.continueToStep2 = page.locator( 'article[data-step="1"] button.js-backwpup-onboarding-step-2' );
		this.continueToStep3 = page.locator( 'article[data-step="2"] button.js-backwpup-onboarding-step-3' );
		this.websiteServerStorage = page.locator( 'article[data-step="3"] button.js-backwpup-toggle-storage[data-storage="FOLDER"]' );
		this.submitOnboarding = page.locator( 'article[data-step="3"] button.js-backwpup-onboarding-submit-form' );
	}

	async goto(): Promise<void> {
		await this.page.goto( '/wp-admin/admin.php?page=backwpuponboarding' );
		await this.page.waitForLoadState( 'networkidle' );
		// Wait for the onboarding form container to be present before any assertion.
		await this.page.waitForSelector( '#backwpup-onboarding-panes', { state: 'attached' } );
	}
}

import { test, expect } from '@playwright/test';
import { loginAsAdmin } from '../fixtures/auth';
import { wpCli } from '../fixtures/wp-cli';
import { OnboardingPage } from '../pages/onboarding';

/**
 * Onboarding flow tests.
 *
 * page=backwpuponboarding is a registered admin page and is always accessible
 * directly. Most tests navigate there without touching the backwpup_onboarding
 * option. Only the redirect test enables the option — and cleans it up itself.
 */
test.describe( 'BackWPup — Onboarding flow', () => {
	test.beforeEach( async ( { page } ) => {
		await loginAsAdmin( page );
	} );

	test( 'Onboarding page loads and shows step 1', async ( { page } ) => {
		const onboarding = new OnboardingPage( page );
		await onboarding.goto();

		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
		// Step 1 is active when its "Save & Continue" button is visible.
		await expect( onboarding.continueToStep2 ).toBeVisible();
	} );

	test( 'BackWPup pages redirect to onboarding while active', async ( { page } ) => {
		wpCli( "eval \"update_site_option( 'backwpup_onboarding', true );\"" );
		try {
			await page.goto( '/wp-admin/admin.php?page=backwpupjobs' );
			await page.waitForLoadState( 'networkidle' );
			expect( page.url() ).toContain( 'page=backwpuponboarding' );
		} finally {
			wpCli( "eval \"delete_site_option( 'backwpup_onboarding' );\"" );
		}
	} );

	test( 'Step 1 → Step 2: advance with Save & Continue', async ( { page } ) => {
		const onboarding = new OnboardingPage( page );
		await onboarding.goto();

		await onboarding.continueToStep2.click();

		// Step 2 is active when its "Save & Continue" button becomes visible.
		await expect( onboarding.continueToStep3 ).toBeVisible( { timeout: 5_000 } );
	} );

	test( 'Step 2 → Step 3: advance with Save & Continue', async ( { page } ) => {
		const onboarding = new OnboardingPage( page );
		await onboarding.goto();

		await onboarding.continueToStep2.click();
		await expect( onboarding.continueToStep3 ).toBeVisible( { timeout: 5_000 } );

		await onboarding.continueToStep3.click();

		// Step 3 is active when the Website Server storage button becomes visible.
		await expect( onboarding.websiteServerStorage ).toBeVisible( { timeout: 5_000 } );
	} );

	test( 'Step 3: selecting Website Server enables the submit button', async ( { page } ) => {
		const onboarding = new OnboardingPage( page );
		await onboarding.goto();

		await onboarding.continueToStep2.click();
		await expect( onboarding.continueToStep3 ).toBeVisible( { timeout: 5_000 } );
		await onboarding.continueToStep3.click();
		await expect( onboarding.websiteServerStorage ).toBeVisible( { timeout: 5_000 } );

		// Submit is disabled until a storage is selected.
		await expect( onboarding.submitOnboarding ).toBeDisabled();

		await onboarding.websiteServerStorage.click();

		await expect( onboarding.submitOnboarding ).toBeEnabled( { timeout: 5_000 } );
	} );

	test( 'Complete full onboarding: submitting redirects to first backup page', async ( { page } ) => {
		// Ensure onboarding option is set so the form submission calls delete_site_option.
		wpCli( "eval \"update_site_option( 'backwpup_onboarding', true );\"" );

		const onboarding = new OnboardingPage( page );
		await onboarding.goto();

		// Step 1 → Step 2
		await onboarding.continueToStep2.click();
		await expect( onboarding.continueToStep3 ).toBeVisible( { timeout: 5_000 } );

		// Step 2 → Step 3
		await onboarding.continueToStep3.click();
		await expect( onboarding.websiteServerStorage ).toBeVisible( { timeout: 5_000 } );

		// Step 3: choose Website Server (local folder) and submit
		await onboarding.websiteServerStorage.click();
		await expect( onboarding.submitOnboarding ).toBeEnabled( { timeout: 5_000 } );
		await onboarding.submitOnboarding.click();

		// After submission the plugin redirects to the first backup page
		// and deletes the backwpup_onboarding option.
		await page.waitForURL( '**/page=backwpupfirstbackup**', { timeout: 15_000 } );
		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
	} );
} );

import { test, expect } from '@playwright/test';
import { loginAsAdmin } from '../fixtures/auth';
import { wpCli } from '../fixtures/wp-cli';

/**
 * Legacy Jobs admin page tests.
 *
 * Verifies that the jobs list renders correctly and that a seed job
 * created by bin/dev-seed.sh appears in the table.
 *
 * Tests that trigger actual backup runs require a license key and are
 * skipped when BACKWPUP_TESTS_LICENSE_KEY is not set.
 */
test.describe( 'BackWPup — Legacy Jobs list', () => {
	test.beforeAll( () => {
		// Ensure onboarding is complete so admin pages don't redirect.
		wpCli( "eval \"delete_site_option( 'backwpup_onboarding' );\"" );
	} );

	test.beforeEach( async ( { page } ) => {
		await loginAsAdmin( page );
	} );

	test( 'Jobs page loads and displays the jobs table', async ( { page } ) => {
		await page.goto( '/wp-admin/admin.php?page=backwpupjobs' );
		await page.waitForLoadState( 'networkidle' );

		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
		// The WP_List_Table renders a <table> with class widefat.
		await expect( page.locator( 'table.widefat' ) ).toBeVisible();
	} );

	test( 'Seed job appears in the jobs list', async ( { page } ) => {
		await page.goto( '/wp-admin/admin.php?page=backwpupjobs' );
		await page.waitForLoadState( 'networkidle' );

		const seedRow = page.locator( 'td', { hasText: 'BackWPup E2E Seed Job' } );
		const count = await seedRow.count();

		if ( count === 0 ) {
			test.skip( true, 'Seed job not found — run bin/dev-seed.sh first' );
			return;
		}

		await expect( seedRow.first() ).toBeVisible();
	} );

	test( 'Job edit page loads for the seed job', async ( { page } ) => {
		// Find the job ID via WP-CLI.
		const jobsJson = wpCli( "eval 'echo json_encode( BackWPup_Option::get_job_ids() );'" );
		let seedJobId: string | null = null;

		try {
			const ids = JSON.parse( jobsJson ) as number[];
			for ( const id of ids ) {
				const name = wpCli( `eval 'echo BackWPup_Option::get( ${ id }, "name" );'` );
				if ( name.trim() === 'BackWPup E2E Seed Job' ) {
					seedJobId = String( id );
					break;
				}
			}
		} catch {
			test.skip( true, 'Could not parse jobs list — run bin/dev-seed.sh first' );
			return;
		}

		if ( ! seedJobId ) {
			test.skip( true, 'Seed job not found — run bin/dev-seed.sh first' );
			return;
		}

		await page.goto( `/wp-admin/admin.php?page=backwpupeditjob&jobid=${ seedJobId }` );
		await page.waitForLoadState( 'networkidle' );

		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
		await expect( page.locator( '#backwpup-page, .wrap' ) ).toBeVisible();
	} );
} );

import { test, expect } from '@playwright/test';
import { loginAsAdmin } from '../fixtures/auth';
import { wpCli } from '../fixtures/wp-cli';
import { DashboardPage } from '../pages/dashboard';
import { SettingsPage } from '../pages/settings';
import { BackupsPage } from '../pages/backups';

/**
 * Smoke tests — verify all BackWPup admin pages load without fatal errors.
 *
 * These tests do not require a license key and run on every PR.
 */
test.describe( 'BackWPup smoke tests', () => {
	test.beforeAll( () => {
		// Ensure onboarding is complete so admin pages don't redirect.
		wpCli( "eval \"delete_site_option( 'backwpup_onboarding' );\"" );
	} );

	test.beforeEach( async ( { page } ) => {
		await loginAsAdmin( page );
	} );

	test( 'Dashboard loads without fatal errors', async ( { page } ) => {
		const dashboard = new DashboardPage( page );
		await dashboard.goto();
		await dashboard.expectNoFatalError();
	} );

	test( 'Settings page loads without fatal errors', async ( { page } ) => {
		const settings = new SettingsPage( page );
		await settings.goto();
		await settings.expectNoFatalError();
		await expect( settings.settingsForm ).toBeVisible();
	} );

	test( 'Settings page has tab navigation', async ( { page } ) => {
		const settings = new SettingsPage( page );
		await settings.goto();
		await expect( settings.tabBar ).toBeVisible();
	} );

	test( 'Backups page loads without fatal errors', async ( { page } ) => {
		const backups = new BackupsPage( page );
		await backups.goto();
		await backups.expectNoFatalError();
	} );

	test( 'Legacy Jobs page loads without fatal errors', async ( { page } ) => {
		await page.goto( '/wp-admin/admin.php?page=backwpupjobs' );
		await page.waitForLoadState( 'networkidle' );
		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
	} );

	test( 'Logs page loads without fatal errors', async ( { page } ) => {
		await page.goto( '/wp-admin/admin.php?page=backwpuplogs' );
		await page.waitForLoadState( 'networkidle' );
		await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
	} );

	test( 'Plugin can be deactivated and reactivated without errors', async () => {
		const deactivate = wpCli( 'plugin deactivate backwpup-pro' );
		expect( deactivate ).toContain( 'Deactivated' );

		const activate = wpCli( 'plugin activate backwpup-pro' );
		expect( activate ).toContain( 'Activated' );
	} );
} );

#!/usr/bin/env bash
# Seed the wp-env environment with test data for E2E tests.
# Idempotent — safe to run multiple times.
set -euo pipefail

cd "$(dirname "$0")/.."

WP="npx @wordpress/env run cli wp"

echo "Seeding test data..."

# Set a dummy license key if provided via env var (enables PRO features).
if [[ -n "${BACKWPUP_TESTS_LICENSE_KEY:-}" ]]; then
  $WP eval "
    \$options = get_option( 'backwpup', [] );
    \$options['license_key'] = '${BACKWPUP_TESTS_LICENSE_KEY}';
    update_option( 'backwpup', \$options );
  "
  echo "  License key set."
fi

# Create a seed backup job (DB-only, local folder) if none exists.
$WP eval '
  foreach ( BackWPup_Option::get_job_ids() as $job_id ) {
      if ( "BackWPup E2E Seed Job" === BackWPup_Option::get( $job_id, "name" ) ) {
          echo "seed-job-exists:" . $job_id;
          return;
      }
  }
  $job_id = BackWPup_Option::create_default_jobs( "BackWPup E2E Seed Job", [ "DBDUMP" ] );
  BackWPup_Option::update( $job_id, "backupdir", WP_CONTENT_DIR . "/uploads/backwpup-e2e-tests/" );
  BackWPup_Option::update( $job_id, "cronselect", "manuell" );
  echo "seed-job-created:" . $job_id;
'

# Mark onboarding as complete so other admin pages don't redirect to onboarding.
$WP eval "delete_site_option( 'backwpup_onboarding' );"

echo "Done seeding."

