import { Page, Locator } from '@playwright/test';

/**
 * Page object for the BackWPup main dashboard.
 * URL: /wp-admin/admin.php?page=backwpup
 */
export class DashboardPage {
	readonly page: Page;
	readonly container: Locator;

	constructor( page: Page ) {
		this.page = page;
		this.container = page.locator( '.backwpup-typography, #wpbody-content' );
	}

	async goto(): Promise<void> {
		await this.page.goto( '/wp-admin/admin.php?page=backwpup' );
		await this.page.waitForLoadState( 'networkidle' );
	}

	async expectNoFatalError(): Promise<void> {
		await this.page.waitForLoadState( 'networkidle' );
		const fatalError = this.page.locator( '.wp-die-message, #error-page' );
		if ( await fatalError.count() > 0 ) {
			throw new Error( `Fatal WordPress error on dashboard: ${ await fatalError.textContent() }` );
		}
	}
}

