1	#!/usr/bin/env node
2	/**
3	 * BackWPup Knowledge Graph Builder
4	 *
5	 * Scans PHP, TypeScript, and JavaScript source files and extracts
6	 * import/dependency relationships into a structured JSON graph stored at
7	 * .aiassistant/graph/dependency-graph.json.
8	 *
9	 * First run: full scan of all source files.
10	 * Subsequent runs: incremental — only files changed since the last recorded commit.
11	 *
12	 * Usage:
13	 *   node bin/build-knowledge-graph.js           # auto (incremental if possible)
14	 *   node bin/build-knowledge-graph.js --full    # force full rebuild
15	 *   node bin/build-knowledge-graph.js --dry-run # print stats without writing
16	 */
17	
18	'use strict';
19	
20	const fs   = require('fs');
21	const path = require('path');
22	const { execSync } = require('child_process');
23	
24	// ---------------------------------------------------------------------------
25	// Config
26	// ---------------------------------------------------------------------------
27	
28	const ROOT        = path.resolve(__dirname, '..');
29	const GRAPH_PATH  = path.join(ROOT, '.aiassistant', 'graph', 'dependency-graph.json');
30	const SCAN_DIRS   = ['src', 'inc', 'pro', 'packages', 'bin'];
31	const ASSET_DIRS  = ['assets', 'resources'];
32	const EXTENSIONS  = { php: ['.php'], js: ['.js', '.ts', '.tsx', '.jsx'] };
33	
34	const ARGS     = process.argv.slice(2);
35	const FORCE    = ARGS.includes('--full');
36	const DRY_RUN  = ARGS.includes('--dry-run');
37	
38	// ---------------------------------------------------------------------------
39	// Git helpers
40	// ---------------------------------------------------------------------------
41	
42	function git(cmd) {
43		try {
44			return execSync(`git -C "${ROOT}" ${cmd}`, { encoding: 'utf8' }).trim();
45		} catch {
46			return null;
47		}
48	}
49	
50	function headSha() {
51		return git('rev-parse HEAD');
52	}
53	
54	/** Returns list of relative file paths changed between two commits. */
55	function changedFiles(fromSha, toSha = 'HEAD') {
56		const out = git(`diff --name-only ${fromSha}..${toSha}`);
57		return out ? out.split('\n').filter(Boolean) : [];
58	}
59	
60	/** Returns all tracked files (for full scan). */
61	function allTrackedFiles() {
62		const out = git('ls-files');
63		return out ? out.split('\n').filter(Boolean) : [];
64	}
65	
66	// ---------------------------------------------------------------------------
67	// PHP parser
68	// ---------------------------------------------------------------------------
69	
70	/**
71	 * Extracts dependency info from a single PHP file.
72	 * @param {string} content
73	 * @returns {{ namespace: string|null, symbols: Array, imports: string[] }}
74	 */
75	function parsePhp(content) {
76		const imports   = [];
77		const symbols   = [];
78		let   namespace = null;
79	
80		// Namespace
81		const nsMatch = content.match(/^\s*namespace\s+([\w\\]+)\s*;/m);
82		if (nsMatch) namespace = nsMatch[1];
83	
84		// Use statements — handles simple, aliased, and grouped forms
85		// e.g. use Foo\Bar; / use Foo\Bar as Baz; / use Foo\{A, B as C, D};
86		const useRe = /^\s*use\s+([\w\\]+)(?:\\{([^}]+)})?\s*(?:as\s+\w+)?\s*;/gm;
87		let m;
88		while ((m = useRe.exec(content)) !== null) {
89			const base    = m[1];
90			const grouped = m[2];
91			if (grouped) {
92				for (const part of grouped.split(',')) {
93					const trimmed = part.trim().replace(/\s+as\s+\w+$/, '');
94					imports.push(`${base}\\${trimmed}`);
95				}
96			} else {
97				imports.push(base.replace(/\s+as\s+\w+$/, '').trim());
98			}
99		}
100	
101		// Class / interface / trait / enum declarations
102		const declRe = /^\s*(abstract\s+|final\s+|readonly\s+)*(class|interface|trait|enum)\s+(\w+)(?:\s+extends\s+([\w\\,\s]+?))?(?:\s+implements\s+([\w\\,\s]+?))?\s*(?:\{|$)/gm;
103		while ((m = declRe.exec(content)) !== null) {
104			const kind       = m[2];
105			const name       = m[3];
106			const rawExtends = m[4] ? m[4].split(',').map(s => s.trim()).filter(Boolean) : [];
107			const rawImpls   = m[5] ? m[5].split(',').map(s => s.trim()).filter(Boolean) : [];
108			symbols.push({ kind, name, extends: rawExtends, implements: rawImpls });
109		}
110	
111		return { namespace, symbols, imports: [...new Set(imports)] };
112	}
113	
114	// ---------------------------------------------------------------------------
115	// JS / TS parser
116	// ---------------------------------------------------------------------------
117	
118	/**
119	 * Extracts import sources from JS/TS files.
120	 * @param {string} content
121	 * @returns {{ imports: string[] }}
122	 */
123	function parseJs(content) {
124		const imports = [];
125	
126		// Static imports: import ... from 'source'
127		const staticRe = /\bimport\s+(?:[\w*{][^'"]*from\s+)?['"]([^'"]+)['"]/g;
128		let m;
129		while ((m = staticRe.exec(content)) !== null) {
130			imports.push(m[1]);
131		}
132	
133		// Dynamic imports: import('source') / require('source')
134		const dynRe = /(?:\bimport|\brequire)\s*\(\s*['"]([^'"]+)['"]\s*\)/g;
135		while ((m = dynRe.exec(content)) !== null) {
136			imports.push(m[1]);
137		}
138	
139		return { imports: [...new Set(imports)] };
140	}
141	
142	// ---------------------------------------------------------------------------
143	// File scanner
144	// ---------------------------------------------------------------------------
145	
146	function isSourceFile(relPath) {
147		const allDirs = [...SCAN_DIRS, ...ASSET_DIRS];
148		return allDirs.some(d => relPath.startsWith(d + '/') || relPath.startsWith(d + '\\'));
149	}
150	
151	function languageOf(relPath) {
152		const ext = path.extname(relPath).toLowerCase();
153		if (EXTENSIONS.php.includes(ext)) return 'php';
154		if (EXTENSIONS.js.includes(ext))  return 'js';
155		return null;
156	}
157	
158	/**
159	 * Parse a single file and return its graph node.
160	 * Returns null if the file cannot be read or is not a recognised source file.
161	 */
162	function processFile(relPath) {
163		const lang = languageOf(relPath);
164		if (!lang) return null;
165		if (!isSourceFile(relPath)) return null;
166	
167		const absPath = path.join(ROOT, relPath);
168		if (!fs.existsSync(absPath)) return null;  // deleted file — caller removes it
169	
170		const content = fs.readFileSync(absPath, 'utf8');
171	
172		if (lang === 'php') {
173			const { namespace, symbols, imports } = parsePhp(content);
174			return { language: 'php', namespace, symbols, imports };
175		}
176	
177		const { imports } = parseJs(content);
178		return { language: 'js', imports };
179	}
180	
181	// ---------------------------------------------------------------------------
182	// Symbol index builder
183	// ---------------------------------------------------------------------------
184	
185	/**
186	 * Rebuilds the symbol_index from the nodes map.
187	 * symbol_index maps "Fully\\Qualified\\ClassName" → "relative/file/path.php"
188	 */
189	function buildSymbolIndex(nodes) {
190		const index = {};
191		for (const [filePath, node] of Object.entries(nodes)) {
192			if (node.language !== 'php' || !node.symbols) continue;
193			for (const sym of node.symbols) {
194				const fqn = node.namespace ? `${node.namespace}\\${sym.name}` : sym.name;
195				index[fqn] = filePath;
196			}
197		}
198		return index;
199	}
200	
201	// ---------------------------------------------------------------------------
202	// Main
203	// ---------------------------------------------------------------------------
204	
205	function loadGraph() {
206		if (fs.existsSync(GRAPH_PATH)) {
207			try {
208				return JSON.parse(fs.readFileSync(GRAPH_PATH, 'utf8'));
209			} catch {
210				// corrupted — start fresh
211			}
212		}
213		return { generated_at: null, base_commit: null, nodes: {}, symbol_index: {} };
214	}
215	
216	function saveGraph(graph) {
217		fs.writeFileSync(GRAPH_PATH, JSON.stringify(graph, null, 2) + '\n', 'utf8');
218	}
219	
