	const absPath = path.join(ROOT, relPath);
	if (!fs.existsSync(absPath)) return null;  // deleted file — caller removes it

	const content = fs.readFileSync(absPath, 'utf8');

	if (lang === 'php') {
		const { namespace, symbols, imports } = parsePhp(content);
