// ---------------------------------------------------------------------------

/**
 * Rebuilds the symbol_index from the nodes map.
 * symbol_index maps "Fully\\Qualified\\ClassName" → "relative/file/path.php"
 */
function buildSymbolIndex(nodes) {
	const index = {};
